package com.mst.repositories;import com.mst.models.UserAccount;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="sale.live",matches="true") class SaleGdnDirectLiveTest{@Test void desktopReadPathsMatchGoldenAce()throws Exception{var p=new Properties();try(var in=Files.newInputStream(Path.of("src/main/resources/application.properties"))){p.load(in);}var j=new JdbcTemplate(new DriverManagerDataSource(p.getProperty("spring.datasource.url"),p.getProperty("spring.datasource.username"),p.getProperty("spring.datasource.password")));j.setQueryTimeout(90);var a=j.queryForMap("SELECT ID,OrganizationId,CompanyId,BranchesId,AppId FROM UserAccount WHERE UserName='numan'");var u=new UserAccount();u.setId(n(a.get("ID")));u.setOrganizationId(n(a.get("OrganizationId")));u.setCompanyId(n(a.get("CompanyId")));u.setBranchesId(n(a.get("BranchesId")));u.setAppId(n(a.get("AppId")));var r=new SaleGdnDirectRepository(j);var d=r.initial(u,58);assertFalse(((List<?>)d.get("customers")).isEmpty());assertFalse(((List<?>)d.get("items")).isEmpty());assertFalse(((List<?>)d.get("warehouses")).isEmpty());assertFalse(((List<?>)d.get("cities")).isEmpty());var h=r.history(u,58);if(!h.isEmpty())assertEquals(124,n(r.record(u,n(h.get(0).get("Id"))).get("DocumentTypeId")));Files.createDirectories(Path.of("migration/sale/evidence"));Files.writeString(Path.of("migration/sale/evidence/gdn-direct-read.txt"),"GDN Direct document 124 GoldenAcedb desktop numbering/customer/item/brand/warehouse/crop/job lot/packing/UOM/city/transporter/history/load paths passed for Numan 78/78/58 year 58. Customers="+((List<?>)d.get("customers")).size()+", items="+((List<?>)d.get("items")).size()+", warehouses="+((List<?>)d.get("warehouses")).size()+", cities="+((List<?>)d.get("cities")).size()+", history="+h.size()+".\n");}static int n(Object o){return o instanceof Number?((Number)o).intValue():0;}}
